			jr z, p_rep_si0_e
			inc hl
			inc de
			djnz p_rep_si0
			xor a
			ld (de), a
p_rep_si0_e:
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_rep_n), de
